package main

// The other tools 'galopin launch' starts (goose, Mistral Vibe, Claude Code).
// Each is wired the way launchOpencode wires opencode: through galopin's local
// proxy (the tool holds only the proxy's secret, never the gateway credential),
// other providers' keys stripped, and no link to Cerea. Config for goose and
// Vibe is generated by the same code as the supervised engines' (goose_engine.go,
// vibe_engine.go) but written to a private temporary directory that is removed
// when the tool exits: the user's own goose and Vibe configuration is never read
// or written.

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"syscall"
	"time"

	"galopin/packaging"
)

// launchTempDir makes a private (0700) directory for one launch, named
// <prefix>-launch-<pid> beside where the opencode launch's TMPDIR lives
// (per-user, never a fixed name under /tmp), with a private tmp/ inside for the
// tool's TMPDIR. The pid in the name lets a later launch sweep the leftovers of
// one that was killed (sweepStaleLaunchDirs).
func launchTempDir(stateDir, prefix string) (string, error) {
	parent := filepath.Dir(opencodeTmpDir(stateDir))
	if err := os.MkdirAll(parent, 0o700); err != nil {
		return "", err
	}
	dir := filepath.Join(parent, fmt.Sprintf("%s-launch-%d", prefix, os.Getpid()))
	_ = os.RemoveAll(dir) // a stale one under a recycled pid
	if err := os.MkdirAll(filepath.Join(dir, "tmp"), 0o700); err != nil {
		return "", err
	}
	return dir, nil
}

var launchDirRe = regexp.MustCompile(`^(opencode|goose|vibe|claude)-launch-(\d+)$`)

// sweepStaleLaunchDirs removes launch directories whose process is gone: what
// SIGKILL, a panic or a power cut left behind (they hold a proxy secret).
func sweepStaleLaunchDirs(stateDir string) {
	parent := filepath.Dir(opencodeTmpDir(stateDir))
	ents, err := os.ReadDir(parent)
	if err != nil {
		return
	}
	for _, e := range ents {
		m := launchDirRe.FindStringSubmatch(e.Name())
		if m == nil || !e.IsDir() {
			continue
		}
		pid, _ := strconv.Atoi(m[2])
		if pid == os.Getpid() || pidAlive(pid) {
			continue
		}
		_ = os.RemoveAll(filepath.Join(parent, e.Name()))
	}
}

// pidAlive is false only when the process is known not to exist.
func pidAlive(pid int) bool {
	p, err := os.FindProcess(pid)
	if err != nil {
		return true
	}
	return !errors.Is(p.Signal(syscall.Signal(0)), os.ErrProcessDone)
}

// launchModels is the gateway's chat models for this credential, as 'galopin
// goose setup' discovers them. When the caller named a model (--model) there is
// nothing to discover: that one name is the whole list and the gateway answers
// for it at request time (an unknown name fails there, the same way for every
// tool).
func (ls *launchSession) launchModels(ctx context.Context, named string) ([]gatewayModel, error) {
	if named != "" {
		return []gatewayModel{{ID: named}}, nil
	}
	cctx, cancel := context.WithTimeout(ctx, modelsRefreshTimeout+30*time.Second)
	defer cancel()
	access, err := accessTokenFor(ls.credsPath, ls.creds)
	if err != nil {
		return nil, fmt.Errorf("signing in with the stored credential to list the models: %w (run 'galopin auth login', or pass --model)", err)
	}
	fctx, fcancel := context.WithTimeout(cctx, modelsRefreshTimeout)
	defer fcancel()
	if models := fetchModels(fctx, ls.creds.Gateway, access, ls.creds.Group); len(gooseModels(models)) > 0 {
		return models, nil
	}
	return nil, fmt.Errorf("model discovery failed or listed no chat model (GET %s/models); pass --model", strings.TrimSuffix(ls.creds.Gateway, "/"))
}

// checkLaunchMode refuses a connectors-only machine: it has no proxy to use.
func (ls *launchSession) checkLaunchMode(tool string) error {
	if ls.creds.Mode == modeConnectors {
		return fmt.Errorf("this machine was enrolled with --connectors-only: it has no proxy for %s to use", tool)
	}
	return nil
}

// resolveToolBin picks the binary to run: an explicit path (or name) first,
// then each candidate in order, then the tool's name on PATH.
func resolveToolBin(explicit, name string, candidates ...string) (string, error) {
	if explicit != "" {
		if strings.ContainsRune(explicit, os.PathSeparator) {
			if fi, err := os.Stat(explicit); err != nil || fi.IsDir() {
				return "", fmt.Errorf("%s: not an executable file", explicit)
			}
			return explicit, nil
		}
		return exec.LookPath(explicit)
	}
	for _, c := range candidates {
		if c == "" {
			continue
		}
		if fi, err := os.Stat(c); err == nil && !fi.IsDir() {
			return c, nil
		}
	}
	p, err := exec.LookPath(name)
	if err != nil {
		return "", fmt.Errorf("%s not found: install it, or pass --%s PATH", name, name)
	}
	return p, nil
}

// firstModel is the model a tool starts on when none was named: the first chat
// model, as the engines do.
func firstModel(ids []string) string {
	if len(ids) == 0 {
		return placeholderModelID
	}
	return ids[0]
}

func gooseIDs(models []gooseModel) []string {
	ids := make([]string, len(models))
	for i, m := range models {
		ids[i] = m.ID
	}
	return ids
}

// writeGooseLaunchConfig writes an interactive goose's config under root: the
// engine's provider file (without the session-id header, which tags usage as a
// Cerea session) and config.yaml (approve mode, keyring and telemetry off), and
// links the user's own session store so `goose session --resume` sees history.
func writeGooseLaunchConfig(root string, creds *credentials, models []gooseModel, model string, conn *launchConnectors) error {
	provider, err := gooseProviderJSON(fmt.Sprintf("127.0.0.1:%d", creds.ShimPort), creds.ShimSecret, models, false)
	if err != nil {
		return err
	}
	for _, d := range []string{"config/custom_providers", "data", "state"} {
		if err := os.MkdirAll(filepath.Join(root, d), 0o700); err != nil {
			return err
		}
	}
	if err := writeFileAtomic(filepath.Join(root, "config", "custom_providers", gooseProviderID+".json"), provider, 0o600); err != nil {
		return err
	}
	cfg := gooseEngineConfigYAML(model)
	if conn != nil {
		ext, err := gooseLaunchExtensionYAML(conn)
		if err != nil {
			return err
		}
		cfg += ext
	}
	if err := writeFileAtomic(filepath.Join(root, "config", "config.yaml"), []byte(cfg), 0o600); err != nil {
		return err
	}
	return linkGooseSessions(root)
}

// launchGoose runs the user's own interactive goose against the gateway.
func launchGoose(ctx context.Context, opts launchOptions) error {
	ls, err := startLaunch(opts)
	if err != nil {
		return err
	}
	if err := ls.checkLaunchMode("goose"); err != nil {
		return err
	}
	bin, err := resolveGooseLaunchBin(opts.gooseBin)
	if err != nil {
		return err
	}
	if got := gooseVersionOf(bin); got == "" {
		ls.logf("warning: could not read %s's version (galopin is tested against goose %s)", bin, packaging.GooseVersion())
	} else if got != packaging.GooseVersion() {
		ls.logf("warning: %s is goose %s; galopin is tested against %s", bin, got, packaging.GooseVersion())
	}
	models, err := ls.launchModels(ctx, opts.model)
	if err != nil {
		return err
	}
	gm := gooseModels(models)
	model := opts.model
	if model == "" {
		model = firstModel(gooseIDs(gm))
	}
	if err := ls.startProxy(opts); err != nil {
		return err
	}
	defer ls.close()

	root, err := launchTempDir(ls.stateDir, "goose")
	if err != nil {
		return err
	}
	defer os.RemoveAll(root)
	creds := *ls.creds
	creds.ShimPort, creds.ShimSecret = ls.port, ls.toolSecret
	conn := ls.startLaunchConnectors(ctx)
	defer conn.close()
	if err := writeGooseLaunchConfig(root, &creds, gm, model, conn); err != nil {
		return fmt.Errorf("writing the temporary goose config: %w", err)
	}
	env := append(gooseEnv(root, launchBaseEnv(opts)), "TMPDIR="+filepath.Join(root, "tmp"))
	args := opts.args
	if len(args) == 0 || strings.HasPrefix(args[0], "-") {
		// `-- --resume` means `session --resume`
		args = append([]string{"session"}, args...)
	}
	ls.logf("local goose (%s), billed to %s; not supervised by Cerea (no Plan/Ask/Auto, no review log)", model, billingLabel(ls.creds))
	ls.logf("goose asks before each tool call (approve mode), in this terminal; your own goose config and extensions are not loaded; galopin's own-state protections need galopin to answer and do not apply")
	return runLaunched(ctx, "goose", bin, args, env)
}

// resolveGooseLaunchBin: --goose, then the copy galopin installed (or the
// engine's override variable), then goose on PATH.
func resolveGooseLaunchBin(explicit string) (string, error) {
	var cands []string
	if b, err := gooseBinary(); err == nil {
		cands = append(cands, b)
	}
	return resolveToolBin(explicit, "goose", cands...)
}

func launchBaseEnv(opts launchOptions) []string {
	if opts.env != nil {
		return opts.env
	}
	return os.Environ()
}

// vibeVersionOf is the last word `bin --version` prints ("vibe 3.1.0" or "3.1.0").
func vibeVersionOf(bin string) string { return gooseVersionOf(bin) }

// resolveVibeLaunchBin: --vibe, then vibe on PATH, then the interactive entry
// point of the copy galopin installed (its venv holds `vibe` beside the
// `vibe-acp` the engine uses).
func resolveVibeLaunchBin(explicit string) (string, error) {
	if explicit != "" {
		return resolveToolBin(explicit, "vibe")
	}
	if p, err := exec.LookPath("vibe"); err == nil {
		return p, nil
	}
	var cands []string
	if exe, err := os.Executable(); err == nil {
		cands = append(cands, filepath.Join(filepath.Dir(exe), vibeInstallDirName, "venv", "bin", "vibe"))
	}
	return resolveToolBin("", "vibe", cands...)
}

// launchVibe runs the user's own interactive Mistral Vibe against the gateway.
func launchVibe(ctx context.Context, opts launchOptions) error {
	ls, err := startLaunch(opts)
	if err != nil {
		return err
	}
	if err := ls.checkLaunchMode("Vibe"); err != nil {
		return err
	}
	bin, err := resolveVibeLaunchBin(opts.vibeBin)
	if err != nil {
		return err
	}
	if got := vibeVersionOf(bin); got == "" {
		ls.logf("warning: could not read %s's version (galopin is tested against Mistral Vibe %s)", bin, packaging.VibeVersion())
	} else if got != packaging.VibeVersion() {
		ls.logf("warning: %s is Mistral Vibe %s; galopin is tested against %s", bin, got, packaging.VibeVersion())
	}
	models, err := ls.launchModels(ctx, opts.model)
	if err != nil {
		return err
	}
	vm := vibeModels(models)
	if len(vm) == 0 {
		return errors.New("the gateway listed no chat model")
	}
	// The first model is Vibe's active one: put the chosen one first.
	if opts.model != "" {
		for j, m := range vm {
			if m.ID == opts.model {
				vm[0], vm[j] = vm[j], vm[0]
			}
		}
	}
	if err := ls.startProxy(opts); err != nil {
		return err
	}
	defer ls.close()

	home, err := launchTempDir(ls.stateDir, "vibe")
	if err != nil {
		return err
	}
	defer os.RemoveAll(home)
	if err := os.MkdirAll(filepath.Join(home, "logs"), 0o700); err != nil {
		return err
	}
	conn := ls.startLaunchConnectors(ctx)
	defer conn.close()
	vibeCfg := vibeConfigTOML(ls.shimAddr(), ls.toolSecret, vm)
	if conn != nil {
		vibeCfg += vibeConnectorsTOML(conn)
	}
	if err := writeFileAtomic(filepath.Join(home, "config.toml"), []byte(vibeCfg), 0o600); err != nil {
		return fmt.Errorf("writing the temporary Vibe config: %w", err)
	}
	if err := resetVibeTrust(home); err != nil {
		return err
	}
	env := append(vibeEnv(home, launchBaseEnv(opts)), "TMPDIR="+filepath.Join(home, "tmp"))
	ls.logf("local Mistral Vibe (%s), billed to %s; not supervised by Cerea (no Plan/Ask/Auto, no review log)", vm[0].ID, billingLabel(ls.creds))
	ls.logf("Vibe asks before each tool call, in this terminal; your own ~/.vibe is not loaded (no folder is trusted); galopin's own-state protections need galopin to answer and do not apply")
	return runLaunched(ctx, "vibe", bin, opts.args, env)
}

// claudeStripPrefixes are the inherited variables that would point Claude Code
// at another provider or hand it another credential (or a third-party cloud
// route): the only upstream is galopin's proxy.
var claudeStripPrefixes = []string{
	"ANTHROPIC_", "CLAUDE_CODE_USE_", "CLAUDE_CODE_SKIP_", "CLAUDE_CODE_OAUTH_TOKEN", "AWS_BEARER_TOKEN_BEDROCK",
	"OPENAI_", "AZURE_OPENAI_", "OPENROUTER_", "GEMINI_", "GOOGLE_API_KEY", "MISTRAL_", "XAI_", "GROQ_", "DEEPSEEK_",
	"CEREBRAS_", "LITELLM_", "OLLAMA_",
}

// claudeLaunchSettings are the variables galopin sets for Claude Code. They are
// also written to a temporary --settings file: a CLI settings file outranks
// the user's ~/.claude/settings.json, whose own "env" block would otherwise win
// over the process environment.
//
// Variable names are Claude Code's documented ones (ANTHROPIC_BASE_URL,
// ANTHROPIC_AUTH_TOKEN sent as "Authorization: Bearer", ANTHROPIC_MODEL, the
// ANTHROPIC_DEFAULT_*_MODEL aliases, CLAUDE_CODE_SUBAGENT_MODEL,
// CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC); they are not verified against a
// pinned release because galopin pins none.
func claudeLaunchSettings(shimAddr, secret, model, small string) [][2]string {
	noProxy := "127.0.0.1,localhost"
	return [][2]string{
		{"ANTHROPIC_BASE_URL", "http://" + shimAddr},
		{"ANTHROPIC_AUTH_TOKEN", secret},
		// Neutralise what a user or repository settings file could switch back
		// on: an API key (sent as X-Api-Key beside the bearer), extra request
		// headers, and the cloud-provider routes that bypass the gateway.
		{"ANTHROPIC_API_KEY", ""},
		{"ANTHROPIC_CUSTOM_HEADERS", ""},
		{"CLAUDE_CODE_USE_BEDROCK", "0"},
		{"CLAUDE_CODE_USE_VERTEX", "0"},
		{"CLAUDE_CODE_USE_FOUNDRY", "0"},
		{"AWS_BEARER_TOKEN_BEDROCK", ""},
		{"ANTHROPIC_MODEL", model},
		{"ANTHROPIC_DEFAULT_OPUS_MODEL", model},
		{"ANTHROPIC_DEFAULT_SONNET_MODEL", model},
		{"ANTHROPIC_DEFAULT_HAIKU_MODEL", small},
		{"ANTHROPIC_SMALL_FAST_MODEL", small},
		{"CLAUDE_CODE_SUBAGENT_MODEL", model},
		{"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC", "1"},
		{"DISABLE_AUTOUPDATER", "1"},
		{"DISABLE_TELEMETRY", "1"},
		{"DISABLE_ERROR_REPORTING", "1"},
		{"NO_PROXY", noProxy},
		{"no_proxy", noProxy},
	}
}

// claudeEnv is the caller's environment with other providers' variables
// removed and galopin's put in. An inherited NO_PROXY is kept and extended.
func claudeEnv(base []string, set [][2]string) []string {
	out := make([]string, 0, len(base)+len(set))
	extraNoProxy := ""
	for _, kv := range base {
		name, val, _ := strings.Cut(kv, "=")
		if (name == "NO_PROXY" || name == "no_proxy") && val != "" {
			extraNoProxy = val
		}
		strip := false
		for _, p := range claudeStripPrefixes {
			if strings.HasPrefix(name, p) {
				strip = true
				break
			}
		}
		if !strip && name != "NO_PROXY" && name != "no_proxy" {
			out = append(out, kv)
		}
	}
	for _, kv := range set {
		v := kv[1]
		if (kv[0] == "NO_PROXY" || kv[0] == "no_proxy") && extraNoProxy != "" {
			v = extraNoProxy + "," + v
		}
		out = append(out, kv[0]+"="+v)
	}
	return out
}

// claudeVersionOf is `claude --version` ("2.1.317 (Claude Code)"), or "".
func claudeVersionOf(bin string) string {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	out, err := exec.CommandContext(ctx, bin, "--version").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// launchClaude runs the user's own interactive Claude Code against the gateway's
// Anthropic-compatible endpoint (/v1/messages) through the local proxy.
func launchClaude(ctx context.Context, opts launchOptions) error {
	ls, err := startLaunch(opts)
	if err != nil {
		return err
	}
	if err := ls.checkLaunchMode("Claude Code"); err != nil {
		return err
	}
	bin, err := resolveToolBin(opts.claudeBin, "claude")
	if err != nil {
		return err
	}
	if v := claudeVersionOf(bin); v == "" {
		ls.logf("warning: could not read %s's version; galopin pins no Claude Code version", bin)
	} else {
		ls.logf("Claude Code %s (galopin pins no Claude Code version; its settings and variable names may change)", v)
	}
	// --model alone is enough: the small model defaults to it, nothing to
	// discover. Otherwise the main model is the gateway's first chat model.
	model, small := opts.model, opts.smallModel
	if model == "" {
		models, err := ls.launchModels(ctx, "")
		if err != nil {
			return err
		}
		model = firstModel(gooseIDs(gooseModels(models)))
	}
	if small == "" {
		small = model
	}
	if err := ls.startProxy(opts); err != nil {
		return err
	}
	defer ls.close()

	set := claudeLaunchSettings(ls.shimAddr(), ls.toolSecret, model, small)
	envBlock := map[string]string{}
	for _, kv := range set {
		envBlock[kv[0]] = kv[1]
	}
	// apiKeyHelper "" turns off a helper from the user's own settings: its key
	// would be sent as X-Api-Key beside the bearer.
	settings, err := json.Marshal(map[string]any{"env": envBlock, "apiKeyHelper": ""})
	if err != nil {
		return err
	}
	dir, err := launchTempDir(ls.stateDir, "claude")
	if err != nil {
		return err
	}
	defer os.RemoveAll(dir)
	settingsPath := filepath.Join(dir, "settings.json")
	if err := writeFileAtomic(settingsPath, settings, 0o600); err != nil {
		return err
	}
	args := []string{"--settings", settingsPath, "--model", model}
	// Connectors: a temporary --mcp-config, merged by Claude Code with the user's
	// own MCP servers (no --strict-mcp-config).
	if conn := ls.startLaunchConnectors(ctx); conn != nil {
		defer conn.close()
		mcpJSON, err := claudeMcpConfigJSON(conn)
		if err != nil {
			return err
		}
		mcpPath := filepath.Join(dir, "mcp.json")
		if err := writeFileAtomic(mcpPath, mcpJSON, 0o600); err != nil {
			return err
		}
		args = append(args, "--mcp-config", mcpPath)
	}
	args = append(args, opts.args...)
	env := append(claudeEnv(launchBaseEnv(opts), set), "TMPDIR="+filepath.Join(dir, "tmp"))
	ls.logf("local Claude Code (%s, small model %s), billed to %s; not supervised by Cerea (no Plan/Ask/Auto, no review log)", model, small, billingLabel(ls.creds))
	ls.logf("Claude Code asks per its own permission settings, in this terminal; your ~/.claude settings still apply except what galopin overrides (endpoint, token, models); galopin's own-state protections need galopin to answer and do not apply")
	return runLaunched(ctx, "claude", bin, args, env)
}
